    buAdobeColors.HSL hsl = new buAdobeColors.HSL();
    hsl.H = buColorVerticalSlider_0.hsl_0.H;
    hsl.S = buColorVerticalSlider_0.hsl_0.S;
    for (int index = 0; index < buColorVerticalSlider_0.Height - 8; ++index)
    {
      hsl.L = 1.0 - (double) index / (double) (buColorVerticalSlider_0.Height - 8);
      Pen pen = new Pen(buAdobeColors.HSL_to_RGB(hsl));
      graphics.DrawLine(pen, 11, index + 4, buColorVerticalSlider_0.Width - 11, index + 4);
    }
  }

