  static void smethod_141(buMultiTextBox buMultiTextBox_0, Place place_0)
  {
    int iEndChar = place_0.iChar;
    int iStartChar = place_0.iChar;
    for (int iChar = place_0.iChar; iChar < buMultiTextBox_0.textSource_0[place_0.iLine].Count; ++iChar)
    {
      char c = buMultiTextBox_0.textSource_0[place_0.iLine][iChar].c;
      if ((char.IsLetterOrDigit(c) ? 1 : (c == '_' ? 1 : 0)) != 0)
        iStartChar = iChar + 1;
      else
        break;
    }
    for (int index = place_0.iChar - 1; index >= 0; --index)
    {
      char c = buMultiTextBox_0.textSource_0[place_0.iLine][index].c;
      if ((char.IsLetterOrDigit(c) ? 1 : (c == '_' ? 1 : 0)) != 0)
        iEndChar = index;
      else
        break;
    }
    buMultiTextBox_0.Selection = new buMutliTextbox.Range(buMultiTextBox_0, iStartChar, place_0.iLine, iEndChar, place_0.iLine);
  }

