  static void smethod_375(
    Point point_0,
    Graphics graphics_0,
    Point point_1,
    WavyLineStyle wavyLineStyle_0)
  {
    if (point_1.X - point_0.X < 2)
    {
      graphics_0.DrawLine(wavyLineStyle_0.method_0(), point_0, point_1);
    }
    else
    {
      int num = -1;
      List<Point> pointList = new List<Point>();
      for (int x = point_0.X; x <= point_1.X; x += 2)
      {
        pointList.Add(new Point(x, point_0.Y + num));
        num = -num;
      }
      graphics_0.DrawLines(wavyLineStyle_0.method_0(), pointList.ToArray());
    }
  }

