  static void smethod_527(int int_0, buClock buClock_0, Graphics graphics_0, Point point_0)
  {
    for (int index = 0; index < 60; ++index)
    {
      bool flag = index % 5 == 0;
      double num1 = (double) (index * 6) * Math.PI / 180.0;
      int num2 = int_0 - 8;
      int num3 = flag ? int_0 - 24 : int_0 - 16 /*0x10*/;
      Point pt1 = new Point(point_0.X + (int) (Math.Sin(num1) * (double) num3), point_0.Y - (int) (Math.Cos(num1) * (double) num3));
      Point pt2 = new Point(point_0.X + (int) (Math.Sin(num1) * (double) num2), point_0.Y - (int) (Math.Cos(num1) * (double) num2));
      using (Pen pen = new Pen(buClock_0.TickColor, flag ? 3f : 1f))
        graphics_0.DrawLine(pen, pt1, pt2);
    }
  }

