  static void smethod_533(buMultiTextBox buMultiTextBox_0, Graphics graphics_0)
  {
    foreach (Hint hint in buMultiTextBox_0.hints_0)
    {
      buMutliTextbox.Range range = hint.Range.Clone();
      range.Normalize();
      Point point1 = buMultiTextBox_0.PlaceToPoint(range.Start);
      Point point2 = buMultiTextBox_0.PlaceToPoint(range.End);
      if ((buMultiTextBox_0.GetVisibleState(range.Start.iLine) != VisibleState.Visible ? 1 : (buMultiTextBox_0.GetVisibleState(range.End.iLine) != 0 ? 1 : 0)) == 0)
      {
        using (Pen pen = new Pen(hint.BorderColor))
        {
          pen.DashStyle = DashStyle.Dash;
          if (range.IsEmpty)
          {
            point1.Offset(1, -1);
            graphics_0.DrawLines(pen, new Point[2]
            {
              point1,
              new Point(point1.X, point1.Y + buMultiTextBox_0.int_0 + 2)
            });
          }
          else
          {
            point1.Offset(-1, -1);
            point2.Offset(1, -1);
            graphics_0.DrawLines(pen, new Point[4]
            {
              new Point(point1.X + buMultiTextBox_0.CharWidth / 2, point1.Y),
              point1,
              new Point(point1.X, point1.Y + buMultiTextBox_0.int_0 + 2),
              new Point(point1.X + buMultiTextBox_0.CharWidth / 2, point1.Y + buMultiTextBox_0.int_0 + 2)
            });
            graphics_0.DrawLines(pen, new Point[4]
            {
              new Point(point2.X - buMultiTextBox_0.CharWidth / 2, point2.Y),
              point2,
              new Point(point2.X, point2.Y + buMultiTextBox_0.int_0 + 2),
              new Point(point2.X - buMultiTextBox_0.CharWidth / 2, point2.Y + buMultiTextBox_0.int_0 + 2)
            });
          }
        }
      }
    }
  }

