  static void smethod_671(buColorBox buColorBox_0)
  {
    Graphics graphics = buColorBox_0.CreateGraphics();
    buAdobeColors.HSL hsl1 = new buAdobeColors.HSL();
    buAdobeColors.HSL hsl2 = new buAdobeColors.HSL();
    hsl1.S = buColorBox_0.hsl_0.S;
    hsl2.S = buColorBox_0.hsl_0.S;
    hsl1.L = 1.0;
    hsl2.L = 0.0;
    for (int index = 0; index < buColorBox_0.Width - 4; ++index)
    {
      hsl1.H = (double) index / (double) (buColorBox_0.Width - 4);
      hsl2.H = hsl1.H;
      LinearGradientBrush linearGradientBrush = new LinearGradientBrush(new Rectangle(2, 2, 1, buColorBox_0.Height - 4), buAdobeColors.HSL_to_RGB(hsl1), buAdobeColors.HSL_to_RGB(hsl2), 90f, false);
      graphics.FillRectangle((Brush) linearGradientBrush, new Rectangle(index + 2, 2, 1, buColorBox_0.Height - 4));
    }
  }

