    using (Pen pen = new Pen(buClock_0.SecondHandColor, buClock_0.SecondHandThickness))
    {
      pen.StartCap = LineCap.Round;
      pen.EndCap = LineCap.Round;
      graphics_0.DrawLine(pen, point_0, pt2);
    }
  }

